export function string() {
  return 'string';
}

export function number() {
  return 'number';
}

/** The mini schema: field specs like "name:string" (order = validation
 * order). */
/** @param {string[]} specs */
export function object(specs) {
  var names = /** @type {string[]} */ ([]);
  var kinds = /** @type {string[]} */ ([]);
  for (var i = 0; i < specs.length; i++) {
    var colon = specs[i].indexOf(':');
    names.push(specs[i].slice(0, colon));
    kinds.push(specs[i].slice(colon + 1));
  }
  return new Schema(names, kinds);
}

export class Schema {
  /** @param {string[]} names */
  /** @param {string[]} kinds */
  constructor(names, kinds) {
    this.names = names;
    this.kinds = kinds;
  }
  /** @param {string[]} values */
  parse(values) {
    var out = /** @type {string[]} */ ([]);
    for (var i = 0; i < values.length; i++) {
      out.push(this.names[i] + '=' + String(values[i]));
    }
    return out;
  }
}

export const z = { string: string, number: number, object: object };
